\label{Part(i)A}
As it deals with surgery on the interior, part~$(i)$ of Theorem~\ref{thmA}
above follows directly from Chernysh's theorem~\cite{Ch}.
Our contribution in this paper is in proving part~$(ii)$.

\label{thm-boundary}
Let $Z\colon Y_0\rightsquigarrow Y_1$ be an elementary bordism as above with $p,q\geq
2$. Then for any metric $g_0\in {\mathcal R}^+(Y_0)$ there exist metrics
$g_1\in {\mathcal R}^+(Y_1)$ and $\bar g\in {\mathcal R}^+(Z,\partial Z)_{g_0,g_1}$ such
that the map
\begin{gather*}
\mu_{Z,\bar{g}}\colon\ {\mathcal R}^{\mathrm{psc}}(X, \partial X)_{g_0} \xrightarrow{\simeq} {\mathcal R}^{\mathrm{psc}}(X\cup Z, Y_1)_{g_1}
\end{gather*}
defined by {\rm (\ref{gluemap-1})}, is a weak homotopy equivalence.

\label{lifthe}
The maps $\mathcal{B}$ and $\mathcal{S}_{\mathcal{H}}^{\mathrm{psc}}$ are homotopy inverse, thus determining a homotopy equi\-valence:
\begin{gather*}
{\mathcal R}^{\mathrm{psc}}(B)\simeq{\mathcal R}_{\mathcal{S}}^{\mathrm{psc}} (M).
\end{gather*}

{\sloppy Let $X_\Sigma$ be an
 $(L,G)$-fibred compact pseudo-manifold with~$L$ a simply connected
 homogeneous space of a compact semisimple Lie group, and
 \mbox{$n-\ell-1\geq 5$}, where $\operatorname{{\text{\rm dim}}} X=n$, $\operatorname{{\text{\rm dim}}} L =\ell$. Let $g_0\in
 {\mathcal R}^{\mathrm{psc}}(X_{\Sigma})\neq \varnothing$ be a base point giving
 corresponding base points, the metrics $g_{\beta X,0}\in {\mathcal R}^{\mathrm{psc}}(\beta
 X)$, $g_{\partial X,0}\in {\mathcal R}^{\mathrm{psc}}(\partial X)$ and $g_{X,0}\in {\mathcal R}^{\mathrm{psc}}(X)_{g_{\partial
 X,0}}$.

 }

If $M_\Sigma$ is spin and
simply connected, then we have the following commutative diagram:
\begin{gather*}                   
 \begin{diagram}
 \setlength{\dgARROWLENGTH}{1.95em}
\node{0\to \pi_q{\mathcal R}^{\mathrm{psc}}(X_\Sigma)_{g_{\beta X,0}}}
 \arrow{e,t}{j_*}
 \arrow{s,l}{\mathrm{inddiff}_{g_{X,0}}}
\node{\pi_q\mathcal{R}^{\mathrm{psc}} (X_\Sigma)}
 \arrow{e,t}{(\mathrm{res}_{\Sigma})_*}
 \arrow{s,l}{\mathrm{inddiff}_{g_0}}
\node{\pi_q\mathcal{R}^{\mathrm{psc}}(\beta X)\to 0}
 \arrow{s,l}{\mathrm{inddiff}_{g_{\beta X,0}}}
 \\
\node{\!\!\! 0\longrightarrow KO_{q+n+1}}
 \arrow{e}
\node{KO_{q+n+1}\oplus KO_{q+n-\ell} }
 \arrow{e}
\node{KO_{q+n-\ell}\to 0,}
\end{diagram}
\end{gather*}
where the homomorphisms $\mathrm{inddiff}_{g_{X,0}}$ and
$\mathrm{inddiff}_{g_{\beta X,0}}$ are both nontrivial whenever the
target groups are. In particular, the homomorphism
\begin{gather*}
 \mathrm{inddiff}_{g_0}\colon\ \pi_q\mathcal{R}^{\mathrm{psc}} (X_\Sigma) \to
 KO_{q+n+1}\oplus KO_{q+n-\ell}
\end{gather*}
is surjective rationally and surjective onto the torsion
of $KO_{q+n+1}\oplus KO_{q+n-\ell}$.
